def thread(user, msg):
  for ref in [msg.in_reply_to] + reversed(msg.references):
    tid = idmap.get(user, ref)
    if tid: break
  else:
    s = normalize_subject(msg.subject)  # strip Re:, Fwd:, whitespace
    tid = recent_subject_thread(user, s, within=7d) or new_thread_id()
  idmap.put(user, msg.rfc822_msgid, tid)
  return tid
